package run.ikaros.reading; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono;
@RestController @RequestMapping("/api/reading") public class ReadingCatalogController{private final ReadingCatalogService service;public ReadingCatalogController(ReadingCatalogService s){service=s;}@PostMapping("/works")public Mono<ReadingWorkView> work(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@Valid@RequestBody CreateReadingWorkRequest r){return service.createWork(o,r);}@GetMapping("/works")public Flux<ReadingWorkView> works(@RequestHeader("X-Ikaros-Actor-Id")UUID o){return service.listWorks(o);}@PostMapping("/editions/{workId}")public Mono<ReadingEditionView> edition(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID workId,@Valid@RequestBody CreateReadingEditionRequest r){return service.createEdition(o,workId,r);}@GetMapping("/editions/{workId}")public Flux<ReadingEditionView> editions(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID workId){return service.listEditions(o,workId);}@PostMapping("/volumes/{editionId}")public Mono<ReadingVolumeView> volume(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID editionId,@Valid@RequestBody CreateReadingVolumeRequest r){return service.createVolume(o,editionId,r);}@GetMapping("/volumes/{editionId}")public Flux<ReadingVolumeView> volumes(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID editionId){return service.listVolumes(o,editionId);}@PostMapping("/chapters/{editionId}")public Mono<ReadingChapterView> chapter(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID editionId,@RequestParam(required=false)UUID volumeId,@Valid@RequestBody CreateReadingChapterRequest r){return service.createChapter(o,editionId,volumeId,r);}@GetMapping("/chapters/{editionId}")public Flux<ReadingChapterView> chapters(@RequestHeader("X-Ikaros-Actor-Id")UUID o,@PathVariable UUID editionId){return service.listChapters(o,editionId);}}
